window.products.push({"id":1166419,"name":"Lodge 3 Quart Dutch Oven with Loop Handles","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/41S-HBNN7TL._AC_.jpg","description":"This pre seasoned 3 quart Dutch Oven eliminates the time and effort of seasoning, offers superior look and appearance to home seasoning and is ready to use right from the box. Tightly controlled metal chemistry and exacting mold tolerances deliver consistent quality for even heating and superior cooking performance. The lid seals in moisture and the excellent heat retention reduces the amount of energy needed for cooking. Hand washing with warm soapy water is recommended to preserve the cookware's original appearance. 10 1/4\" diameter, 3\" deep.","images":["https://m.media-amazon.com/images/I/41S-HBNN7TL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Lodge","source_asin":"B00138WMKE","category_path":"Home & Kitchen"},"sku":"BM-1166419","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00138WMKE","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00138WMKE","price_pending":true,"merchant_ready":false});
